body.script:
      if ('serviceWorker' in navigator) {
            window.addEventListener('load', () => {
                navigator.serviceWorker.register('/sw.js');
            });
        }

        const problems = [
            {
                type: 'circle-area',
                generate: () => {
                    const r = Math.floor(Math.random() * 10) + 2;
                    const area = (Math.PI * r * r).toFixed(2);
                    return {
                        question: 'Find the area of the circle.',
                        given: `Radius: <span>${r} cm</span>`,
                        answer: `${area} cm²`,
                        svg: `<svg viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg">
                            <circle cx="60" cy="60" r="44" fill="rgba(8,145,178,0.08)" stroke="#0891b2" stroke-width="1.5"/>
                            <line x1="60" y1="60" x2="104" y2="60" stroke="#c8553d" stroke-width="1.5" stroke-dasharray="4,2"/>
                            <text x="78" y="55" font-size="10" fill="#c8553d" font-family="DM Mono,monospace">r=${r}</text>
                            <circle cx="60" cy="60" r="2.5" fill="#0891b2"/>
                        </svg>`
                    };
                }
            },
            {
                type: 'circle-circumference',
                generate: () => {
                    const r = Math.floor(Math.random() * 10) + 2;
                    const circ = (2 * Math.PI * r).toFixed(2);
                    return {
                        question: 'Find the circumference of the circle.',
                        given: `Radius: <span>${r} cm</span>`,
                        answer: `${circ} cm`,
                        svg: `<svg viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg">
                            <circle cx="60" cy="60" r="44" fill="rgba(8,145,178,0.05)" stroke="#0891b2" stroke-width="2" stroke-dasharray="6,3"/>
                            <line x1="60" y1="60" x2="104" y2="60" stroke="#c8553d" stroke-width="1.5" stroke-dasharray="4,2"/>
                            <text x="78" y="55" font-size="10" fill="#c8553d" font-family="DM Mono,monospace">r=${r}</text>
                            <circle cx="60" cy="60" r="2.5" fill="#0891b2"/>
                        </svg>`
                    };
                }
            },
            {
                type: 'triangle-area',
                generate: () => {
                    const b = Math.floor(Math.random() * 12) + 3;
                    const h = Math.floor(Math.random() * 12) + 3;
                    const area = (0.5 * b * h).toFixed(1);
                    return {
                        question: 'Find the area of the triangle.',
                        given: `Base: <span>${b} cm</span>, Height: <span>${h} cm</span>`,
                        answer: `${area} cm²`,
                        svg: `<svg viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg">
                            <polygon points="60,16 14,104 106,104" fill="rgba(200,85,61,0.07)" stroke="#c8553d" stroke-width="1.5"/>
                            <line x1="60" y1="16" x2="60" y2="104" stroke="#0891b2" stroke-width="1.5" stroke-dasharray="4,2"/>
                            <text x="63" y="66" font-size="9" fill="#0891b2" font-family="DM Mono,monospace">h=${h}</text>
                            <text x="28" y="115" font-size="9" fill="#c8553d" font-family="DM Mono,monospace">b=${b}</text>
                        </svg>`
                    };
                }
            },
            {
                type: 'rectangle-area',
                generate: () => {
                    const w = Math.floor(Math.random() * 14) + 3;
                    const h = Math.floor(Math.random() * 10) + 3;
                    const area = w * h;
                    return {
                        question: 'Find the area of the rectangle.',
                        given: `Width: <span>${w} cm</span>, Height: <span>${h} cm</span>`,
                        answer: `${area} cm²`,
                        svg: `<svg viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg">
                            <rect x="12" y="32" width="96" height="60" fill="rgba(8,145,178,0.07)" stroke="#0891b2" stroke-width="1.5"/>
                            <text x="42" y="67" font-size="10" fill="#0891b2" font-family="DM Mono,monospace">${w} cm</text>
                            <text x="100" y="67" font-size="9" fill="#c8553d" font-family="DM Mono,monospace" transform="rotate(90,100,67)">${h}</text>
                        </svg>`
                    };
                }
            },
            {
                type: 'rectangle-perimeter',
                generate: () => {
                    const w = Math.floor(Math.random() * 14) + 3;
                    const h = Math.floor(Math.random() * 10) + 3;
                    const perim = 2 * (w + h);
                    return {
                        question: 'Find the perimeter of the rectangle.',
                        given: `Width: <span>${w} cm</span>, Height: <span>${h} cm</span>`,
                        answer: `${perim} cm`,
                        svg: `<svg viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg">
                            <rect x="12" y="32" width="96" height="60" fill="rgba(8,145,178,0.05)" stroke="#0891b2" stroke-width="2" stroke-dasharray="5,3"/>
                            <text x="42" y="27" font-size="10" fill="#c8553d" font-family="DM Mono,monospace">${w} cm</text>
                            <text x="1" y="67" font-size="9" fill="#c8553d" font-family="DM Mono,monospace">${h}</text>
                        </svg>`
                    };
                }
            },
            {
                type: 'pythagorean',
                generate: () => {
                    const triples = [[3,4,5],[5,12,13],[8,15,17],[7,24,25],[6,8,10],[9,12,15]];
                    const [a, b, c] = triples[Math.floor(Math.random() * triples.length)];
                    return {
                        question: 'Find the hypotenuse (c) using the Pythagorean theorem.',
                        given: `a = <span>${a} cm</span>, b = <span>${b} cm</span>`,
                        answer: `c = ${c} cm`,
                        svg: `<svg viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg">
                            <polygon points="14,100 14,28 100,100" fill="rgba(200,85,61,0.07)" stroke="#c8553d" stroke-width="1.5"/>
                            <rect x="14" y="88" width="12" height="12" fill="none" stroke="#0891b2" stroke-width="1.2"/>
                            <text x="2" y="68" font-size="9" fill="#0891b2" font-family="DM Mono,monospace">a=${a}</text>
                            <text x="44" y="114" font-size="9" fill="#0891b2" font-family="DM Mono,monospace">b=${b}</text>
                            <text x="52" y="60" font-size="9" fill="#c8553d" font-family="DM Mono,monospace" transform="rotate(-42,52,60)">c=?</text>
                        </svg>`
                    };
                }
            },
            {
                type: 'square-area',
                generate: () => {
                    const s = Math.floor(Math.random() * 12) + 2;
                    const area = s * s;
                    return {
                        question: 'Find the area of the square.',
                        given: `Side length: <span>${s} cm</span>`,
                        answer: `${area} cm²`,
                        svg: `<svg viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg">
                            <rect x="18" y="18" width="84" height="84" fill="rgba(8,145,178,0.07)" stroke="#0891b2" stroke-width="1.5"/>
                            <text x="42" y="12" font-size="10" fill="#c8553d" font-family="DM Mono,monospace">${s} cm</text>
                            <line x1="18" y1="8" x2="102" y2="8" stroke="#c8553d" stroke-width="1" opacity="0.4"/>
                            <line x1="18" y1="6" x2="18" y2="10" stroke="#c8553d" stroke-width="1" opacity="0.4"/>
                            <line x1="102" y1="6" x2="102" y2="10" stroke="#c8553d" stroke-width="1" opacity="0.4"/>
                        </svg>`
                    };
                }
            },
            {
                type: 'trapezoid-area',
                generate: () => {
                    const a = Math.floor(Math.random() * 10) + 4;
                    const b = Math.floor(Math.random() * 10) + 2;
                    const h = Math.floor(Math.random() * 8) + 3;
                    const area = (0.5 * (a + b) * h).toFixed(1);
                    return {
                        question: 'Find the area of the trapezoid.',
                        given: `Base a: <span>${a} cm</span>, Base b: <span>${b} cm</span>, Height: <span>${h} cm</span>`,
                        answer: `${area} cm²`,
                        svg: `<svg viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg">
                            <polygon points="22,100 98,100 82,30 38,30" fill="rgba(200,85,61,0.07)" stroke="#c8553d" stroke-width="1.5"/>
                            <line x1="60" y1="30" x2="60" y2="100" stroke="#0891b2" stroke-width="1.5" stroke-dasharray="4,2"/>
                            <text x="63" y="70" font-size="9" fill="#0891b2" font-family="DM Mono,monospace">h=${h}</text>
                            <text x="30" y="115" font-size="9" fill="#c8553d" font-family="DM Mono,monospace">a=${a}</text>
                            <text x="44" y="24" font-size="9" fill="#c8553d" font-family="DM Mono,monospace">b=${b}</text>
                        </svg>`
                    };
                }
            }
        ];

        const mathLines = [
            'A = πr² solving for radius when area = 50.27',
            'V = (4/3)πr³ find volume with radius 5cm',
            'F = ma where m = 10kg and a = 9.8m/s²',
            'E = mc² calculating energy from mass 5kg',
            'P = I²R resistance is 100Ω current is 2A',
            'd = vt + (1/2)at² find distance with v=20, a=2, t=5',
            'C = 5/9(F - 32) convert 98.6°F to Celsius',
            'x = (-b ± √(b²-4ac))/2a quadratic formula',
            'sin²θ + cos²θ = 1 verify identity',
            'lim(x→0) sin(x)/x = 1 limit evaluation',
            'ΔG = ΔH - TΔS Gibbs free energy',
            'log₁₀(x) + log₁₀(y) = log₁₀(xy) logarithm rule',
            'v² = u² + 2as find velocity given initial 5m/s, a=3, s=10',
            'I = mαr² moment of inertia calculation',
            'Z = √(R² + (ωL - 1/ωC)²) impedance in circuit'
        ];

        let currentAnswer = '';
        let answerRevealed = false;

        function loadNewProblem() {
            answerRevealed = false;
            const answerEl = document.getElementById('geoAnswer');
            const revealBtn = document.getElementById('geoRevealBtn');
            answerEl.style.display = 'none';
            revealBtn.textContent = 'Show';

            const problem = problems[Math.floor(Math.random() * problems.length)];
            const data = problem.generate();

            document.getElementById('geoVisual').innerHTML = data.svg;
            document.getElementById('geoProblemText').textContent = data.question;
            document.getElementById('geoGiven').innerHTML = data.given;
            currentAnswer = data.answer;
        }

        function revealAnswer() {
            const answerEl = document.getElementById('geoAnswer');
            const revealBtn = document.getElementById('geoRevealBtn');
            if (!answerRevealed) {
                answerEl.textContent = currentAnswer;
                answerEl.style.display = 'inline';
                answerEl.classList.remove('answer-visible');
                void answerEl.offsetWidth;
                answerEl.classList.add('answer-visible');
                revealBtn.textContent = 'Hide';
                answerRevealed = true;
            } else {
                answerEl.style.display = 'none';
                revealBtn.textContent = 'Show';
                answerRevealed = false;
            }
        }

        function generateMathTypewriter() {
            const container = document.getElementById('mathTypewriter');
            const width = window.innerWidth;
            const height = window.innerHeight;

            for (let i = 0; i < mathLines.length; i++) {
                const line = mathLines[Math.floor(Math.random() * mathLines.length)];
                const x = Math.random() * (width - 400);
                const y = Math.random() * (height - 40);
                const rotation = (Math.random() - 0.5) * 15;

                const element = document.createElement('div');
                element.className = 'math-line';
                element.textContent = line;
                element.style.left = x + 'px';
                element.style.top = y + 'px';
                element.style.transform = `rotate(${rotation}deg)`;

                container.appendChild(element);
            }
        }

        loadNewProblem();
        generateMathTypewriter();

        function easeInOutCubic(t) {
            return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
        }

        function animateCursorToButton() {
            const cursor = document.getElementById('fakeCursor');
            const ripple = document.getElementById('cursorRipple');
            const btn = document.getElementById('newProblemBtn');

            const btnRect = btn.getBoundingClientRect();
            const targetX = btnRect.left + btnRect.width / 2 - 10;
            const targetY = btnRect.top + btnRect.height / 2 - 10;

            const startX = targetX - 160 - Math.random() * 100;
            const startY = targetY + 50 + Math.random() * 70;

            cursor.style.left = startX + 'px';
            cursor.style.top = startY + 'px';
            cursor.style.transition = 'opacity 0.35s ease';
            cursor.style.opacity = '0';

            requestAnimationFrame(() => {
                requestAnimationFrame(() => {
                    cursor.style.opacity = '1';
                });
            });

            const duration = 1000 + Math.random() * 400;
            const startTime = performance.now();

            function moveCursor(now) {
                const elapsed = now - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const eased = easeInOutCubic(progress);

                const currentX = startX + (targetX - startX) * eased;
                const currentY = startY + (targetY - startY) * eased;

                cursor.style.left = currentX + 'px';
                cursor.style.top = currentY + 'px';

                if (progress < 1) {
                    requestAnimationFrame(moveCursor);
                } else {
                    cursor.style.transform = 'scale(0.82)';

                    ripple.style.left = (targetX + 10 - 14) + 'px';
                    ripple.style.top = (targetY + 10 - 14) + 'px';
                    ripple.style.animation = 'none';
                    void ripple.offsetWidth;
                    ripple.style.animation = 'ripple-out 0.5s ease-out forwards';

                    loadNewProblem();

                    setTimeout(() => {
                        cursor.style.transform = 'scale(1)';
                    }, 160);

                    setTimeout(() => {
                        cursor.style.transition = 'opacity 0.5s ease';
                        cursor.style.opacity = '0';
                    }, 520);
                }
            }

            requestAnimationFrame(moveCursor);
        }

        function scheduleNext(isFirst) {
            const delay = isFirst ? 1800 : (7000 + Math.random() * 6000);
            setTimeout(() => {
                animateCursorToButton();
                scheduleNext(false);
            }, delay);
        }

        scheduleNext(true);
